//! Polynomial for erf(u)/u on u in [0,4], evaluated in FP64 to avoid biased
//! FP32 approximation errors accumulating through SAM. Generated by
//! tools/gelu_coefficients.py; original scalar erf remains the test oracle.
const COEFFICIENTS: [f64; 25] = [
    0.3535309956434042,
    -0.17657623330131395,
    0.13167511689487213,
    -0.10771044253465967,
    0.09020899410462269,
    -0.07472786555551839,
    0.05988690511197251,
    -0.045765113153012175,
    0.03306063154499496,
    -0.02247354642797403,
    0.014349604294982332,
    -0.0086063304448453,
    0.004853538144470804,
    -0.0025778675310721144,
    0.0012926203228926165,
    -0.0006137232207402123,
    0.000275581642636098,
    -0.00011658001225441685,
    4.7719778958708044e-05,
    -1.9600063096731912e-05,
    7.037026807665831e-06,
    -1.7978250980377164e-06,
    6.997212767600998e-07,
    -4.854053258895874e-07,
    1.373887062072754e-07,
];

pub(super) fn apply(values: &mut [f32]) {
    for x in values {
        let u = *x * std::f32::consts::FRAC_1_SQRT_2;
        let a = u.abs().min(4.) as f64;
        let t = a * a * 0.125 - 1.;
        let mut p = COEFFICIENTS[24];
        for &coefficient in COEFFICIENTS[..24].iter().rev() {
            p = p.mul_add(t, coefficient);
        }
        // At |u| >= 4, erf rounds to +/-1 in FP32. Clamping also prevents
        // polynomial overflow for extreme finite inputs; NaNs survive x below.
        let erf = ((a * p) as f32).copysign(u);
        *x *= 0.5 * (1. + erf);
    }
}
